def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * (3*w) for _ in range(3*h)]
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                for dr, dc in ((0,1),(1,0),(1,2),(2,1)):
                    out[3*r+dr][3*c+dc] = v
                # The demo mosaics show the same motif in each tile, with a
                # two-cell diagonal extension for the upper-right and lower-left.
                if (r == 0 and c == 2) or (r == 2 and c == 0):
                    for dr, dc in ((0,2),(2,0)):
                        out[3*r+dr][3*c+dc] = v
    return out
